    // S-domain: write to RAM
    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst) begin
            w_ptr <= {PTR_WIDTH{1'b0}};
            w_ptr_gray <= {PTR_WIDTH{1'b0}};
            s_in_frame <= 1'b0;
            s_frame_overflow <= 1'b0;
            s_frame_bad <= 1'b0;
            s_frame_good <= 1'b0;
            s_overflow_pulse <= 1'b0;
            s_bad_frame_pulse <= 1'b0;
            s_good_frame_pulse <= 1'b0;
            s_paused <= 1'b0;
        end else begin
            // Gray code update
            w_ptr_gray <= (w_ptr ^ (w_ptr >> 1));

            // Pause logic
            if (PAUSE_ENABLE) begin
                if (s_pause_req_s2 && !s_paused) begin
                    s_paused <= 1'b1;
                end else if (!s_pause_req_s2 && s_paused) begin
                    s_paused <= 1'b0;
                end
            end

            // Frame tracking
            if (s_write_en) begin
                if (s_axis_tlast) begin
                    s_in_frame <= 1'b0;
                    if (s_frame_overflow) begin
                        s_overflow_pulse <= 1'b1;
                        s_frame_overflow <= 1'b0;
                    end
                    if (s_frame_bad) begin
                        s_bad_frame_pulse <= 1'b1;
                        s_frame_bad <= 1'b0;
                    end
                    if (!s_frame_overflow && !s_frame_bad) begin
                        s_good_frame_pulse <= 1'b1;
                    end
                end else begin
                    s_in_frame <= 1'b1;
                end
            end else begin
                s_overflow_pulse <= 1'b0;
                s_bad_frame_pulse <= 1'b0;
                s_good_frame_pulse <= 1'b0;
            end

            // Write to RAM
            if (s_write_en) begin
                ram[w_ptr[ADDR_WIDTH-1:0]] <= {s_axis_tdata, s_axis_tkeep, s_axis_tlast, s_axis_tid, s_axis_tdest, s_axis_tuser};
                w_ptr <= w_ptr + 1'b1;
            end
        end
    end

    // S-domain: compute full
    wire [PTR_WIDTH-1:0] w_ptr_bin = w_ptr;
    wire [PTR_WIDTH-1:0] r_ptr_bin_sync = r_ptr_gray_s2;
    wire [PTR_WIDTH-1:0] r_ptr_bin_from_gray;

    // Convert gray to binary
    function [PTR_WIDTH-1:0] gray_to_bin;
        input [PTR_WIDTH-1:0] gray;
        integer i;
        begin
            gray_to_bin[PTR_WIDTH-1] = gray[PTR_WIDTH-1];
            for (i = PTR_WIDTH-2; i >= 0; i = i - 1) begin
                gray_to_bin[i] = gray_to_bin[i+1] ^ gray[i];
            end
        end
    endfunction

    assign r_ptr_bin_from_gray = gray_to_bin(r_ptr_gray_s2);

    // Full condition: write pointer is one ahead of read pointer (mod DEPTH)
    assign s_full = (w_ptr[ADDR_WIDTH-1:0] == r_ptr_bin_from_gray[ADDR_WIDTH-1:0]) &&
                    (w_ptr[PTR_WIDTH-1] != r_ptr_bin_from_gray[PTR_WIDTH-1]);

    // Empty condition
    assign s_empty = (w_ptr == r_ptr_bin_from_gray);

    // S-domain: tready
    wire s_tready_base = !s_full && !s_paused;
    assign s_axis_tready = s_tready_base;

    // S-domain: status
    wire [PTR_WIDTH-1:0] s_depth = w_ptr - r_ptr_bin_from_gray;
    assign s_status_depth = s_depth;
    assign s_status_depth_commit = s_depth;
    assign s_status_overflow = s_overflow_pulse;
    assign s_status_bad_frame = s_bad_frame_pulse;
    assign s_status_good_frame = s_good_frame_pulse;

    // S-domain: pause ack
    assign s_pause_ack = s_paused;

    // M-domain: read from RAM
    always @(posedge m_clk or posedge m_rst) begin
        if (m_rst) begin
            r_ptr <= {PTR_WIDTH{1'b0}};
            r_ptr_gray <= {PTR_WIDTH{1'b0}};
            m_in_frame <= 1'b0;
            m_frame_overflow <= 1'b0;
            m_frame_bad <= 1'b0;
            m_frame_good <= 1'b0;
            m_overflow_pulse <= 1'b0;
            m_bad_frame_pulse <= 1'b0;
            m_good_frame_pulse <= 1'b0;
            m_paused <= 1'b0;
        end else begin
            // Gray code update
            r_ptr_gray <= (r_ptr ^ (r_ptr >> 1));

            // Pause logic
            if (PAUSE_ENABLE) begin
                if (m_pause_req_s2 && !m_paused) begin
                    m_paused <= 1'b1;
                end else if (!m_pause_req_s2 && m_paused) begin
                    m_paused <= 1'b0;
                end
            end

            // Read from RAM
            if (m_read_en) begin
                r_ptr <= r_ptr + 1'b1;
            end
        end
    end

    // M-domain: compute empty
    wire [PTR_WIDTH-1:0] w_ptr_bin_sync = w_ptr_gray_s2;
    wire [PTR_WIDTH-1:0] w_ptr_bin_from_gray;
    assign w_ptr_bin_from_gray = gray_to_bin(w_ptr_gray_s2);

    assign m_empty = (r_ptr == w_ptr_bin_from_gray);
    assign m_full = 1'b0; // M side is read side, never full

    // M-domain: tvalid
    wire m_tvalid_base = !m_empty && !m_paused;
    assign m_axis_tvalid = m_tvalid_base;

    // M-domain: output data
    wire [BEAT_W-1:0] m_ram_data;
    assign m_ram_data = ram[r_ptr[ADDR_WIDTH-1:0]];

    // Extract fields
    wire [S_DATA_WIDTH-1:0] m_tdata_s = m_ram_data[S_DATA_WIDTH-1:0];
    wire [S_KEEP_W-1:0] m_tkeep_s = m_ram_data[S_DATA_WIDTH+S_KEEP_W-1:S_DATA_WIDTH];
    wire m_tlast_s = m_ram_data[S_DATA_WIDTH+S_KEEP_W];
    wire [ID_W-1:0] m_tid_s = m_ram_data[S_DATA_WIDTH+S_KEEP_W+1+ID_W-1:S_DATA_WIDTH+S_KEEP_W+1];
    wire [DEST_W-1:0] m_tdest_s = m_ram_data[S_DATA_WIDTH+S_KEEP_W+1+ID_W+DEST_W-1:S_DATA_WIDTH+S_KEEP_W+1+ID_W];
    wire [USER_W-1:0] m_tuser_s = m_ram_data[BEAT_W-1:S_DATA_WIDTH+S_KEEP_W+1+ID_W+DEST_W];

    // Width conversion: S to M
    // For simplicity, assume S_DATA_WIDTH == M_DATA_WIDTH
