    // For simplicity, let's assume S_DATA_WIDTH == M_DATA_WIDTH
    // and S_KEEP_WIDTH == M_KEEP_WIDTH

    // If they differ, we need more complex logic
    // Let's implement the simple case

    // M-domain: output
    assign m_axis_tdata = m_tdata_s[M_DATA_WIDTH-1:0];
    assign m_axis_tkeep = m_tkeep_s[M_KEEP_W-1:0];
    assign m_axis_tlast = m_tlast_s;
    assign m_axis_tid = m_tid_s[ID_W-1:0];
    assign m_axis_tdest = m_tdest_s[DEST_W-1:0];
    assign m_axis_tuser = m_tuser_s[USER_W-1:0];

    // M-domain: status
    wire [PTR_WIDTH-1:0] m_depth = w_ptr_bin_from_gray - r_ptr;
    assign m_status_depth = m_depth;
    assign m_status_depth_commit = m_depth;
    assign m_status_overflow = m_overflow_pulse;
    assign m_status_bad_frame = m_bad_frame_pulse;
    assign m_status_good_frame = m_good_frame_pulse;

