            s_good_frame_s2 <= 1'b0;
            m_overflow_s1 <= 1'b0;
            m_overflow_s2 <= 1'b0;
            m_bad_frame_s1 <= 1'b0;
            m_bad_frame_s2 <= 1'b0;
            m_good_frame_s1 <= 1'b0;
            m_good_frame_s2 <= 1'b0;
            w_ptr_bin_s1 <= {PTR_WIDTH{1'b0}};
            w_ptr_bin_s2 <= {PTR_WIDTH{1'b0}};
            r_ptr_bin_s1 <= {PTR_WIDTH{1'b0}};
            r_ptr_bin_s2 <= {PTR_WIDTH{1'b0}};
        end else begin
            w_ptr_gray_s1 <= w_ptr_gray;
            w_ptr_gray_s2 <= w_ptr_gray_s1;
            r_ptr_gray_s1 <= r_ptr_gray;
            r_ptr_gray_s2 <= r_ptr_gray_s1;
