            s_good_frame_s1 <= s_good_frame_pulse;
            s_good_frame_s2 <= s_good_frame_s1;
            m_overflow_s1 <= m_overflow_pulse;
            m_overflow_s2 <= m_overflow_s1;
            m_bad_frame_s1 <= m_bad_frame_pulse;
            m_bad_frame_s2 <= m_bad_frame_s1;
            m_good_frame_s1 <= m_good_frame_pulse;
            m_good_frame_s2 <= m_good_frame_s1;
            w_ptr_bin_s1 <= w_ptr;
